solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <set>
#include <string>
#include <vector>

struct Item { int id; std::string name; std::uint64_t size; std::string modified; };

namespace
{
    std::string formatSize(std::uint64_t bytes)
    {
        if (bytes < 1024) return std::to_string(bytes) + (bytes == 1 ? " byte" : " bytes");
        const char* units[]{ "KB", "MB", "GB", "TB" };
        int u{ 0 };
        std::uint64_t div{ 1024 };
        while (u < 3 && bytes / div >= 1024) { div *= 1024; ++u; }
        const std::uint64_t whole{ bytes / div };
        std::string text;
        if (whole >= 100) text = std::to_string(whole);
        else if (whole >= 10) { const std::uint64_t t{ bytes * 10 / div }; text = std::to_string(t / 10) + "." + std::to_string(t % 10); }
        else { const std::uint64_t h{ bytes * 100 / div }; text = std::to_string(h / 100) + "." + (h % 100 < 10 ? "0" : "") + std::to_string(h % 100); }
        return text + " " + units[u];
    }

    bool naturalLess(const std::string& a, const std::string& b)
    {
        std::size_t i{ 0 }, j{ 0 };
        while (i < a.size() && j < b.size())
        {
            if (std::isdigit(static_cast<unsigned char>(a[i])) && std::isdigit(static_cast<unsigned char>(b[j])))
            {
                std::size_t ei{ i }, ej{ j };
                while (ei < a.size() && std::isdigit(static_cast<unsigned char>(a[ei]))) ++ei;
                while (ej < b.size() && std::isdigit(static_cast<unsigned char>(b[ej]))) ++ej;
                std::size_t si{ i }, sj{ j };
                while (si + 1 < ei && a[si] == '0') ++si;
                while (sj + 1 < ej && b[sj] == '0') ++sj;
                const std::string na{ a.substr(si, ei - si) }, nb{ b.substr(sj, ej - sj) };
                if (na.size() != nb.size()) return na.size() < nb.size();
                if (na != nb) return na < nb;
                if (ei - i != ej - j) return ei - i < ej - j;
                i = ei; j = ej;
                continue;
            }
            const int ca{ std::tolower(static_cast<unsigned char>(a[i])) }, cb{ std::tolower(static_cast<unsigned char>(b[j])) };
            if (ca != cb) return ca < cb;
            ++i; ++j;
        }
        if (i < a.size() || j < b.size()) return i >= a.size();
        return a < b;
    }

    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }
}

class ResultList
{
public:
    void setItems(std::vector<Item> items)
    {
        m_items = std::move(items);
        m_filter.clear();
        m_selected.clear();
        m_anchor = -1;
        rebuild();
    }

    void setFilter(const std::string& text)
    {
        m_filter = lower(text);
        rebuild();
        std::set<int> visible;
        for (int i : m_rows) visible.insert(m_items[static_cast<std::size_t>(i)].id);
        for (auto it{ m_selected.begin() }; it != m_selected.end();) it = visible.count(*it) ? std::next(it) : m_selected.erase(it);
    }

    void clickColumn(int column)
    {
        if (column == m_column) m_ascending = !m_ascending;
        else { m_column = column; m_ascending = true; }
        rebuild();
    }

    int sortColumn() const { return m_column; }
    bool ascending() const { return m_ascending; }
    int count() const { return static_cast<int>(m_rows.size()); }
    int idAt(int row) const { return valid(row) ? item(row).id : -1; }

    std::string cellText(int row, int column) const
    {
        if (!valid(row)) return "";
        const Item& it{ item(row) };
        return column == 0 ? it.name : column == 1 ? formatSize(it.size) : it.modified;
    }

    void click(int row)
    {
        if (!valid(row)) return;
        m_selected = { idAt(row) };
        m_anchor = idAt(row);
    }

    void ctrlClick(int row)
    {
        if (!valid(row)) return;
        const int id{ idAt(row) };
        if (!m_selected.erase(id)) m_selected.insert(id);
        m_anchor = id;
    }

    void shiftClick(int row)
    {
        if (!valid(row)) return;
        const int anchorRow{ rowOf(m_anchor) };
        if (anchorRow < 0) { click(row); return; }
        m_selected.clear();
        for (int r{ std::min(anchorRow, row) }; r <= std::max(anchorRow, row); ++r) m_selected.insert(idAt(r));
    }

    std::vector<int> selectedIds() const
    {
        std::vector<int> out;
        for (int r{ 0 }; r < count(); ++r) if (m_selected.count(idAt(r))) out.push_back(idAt(r));
        return out;
    }

    std::string status() const
    {
        const std::size_t n{ m_items.size() };
        const std::string noun{ n == 1 ? " item" : " items" };
        std::string s{ m_filter.empty() ? std::to_string(n) + noun : std::to_string(m_rows.size()) + " of " + std::to_string(n) + noun + " shown" };
        if (!m_selected.empty()) s += ", " + std::to_string(m_selected.size()) + " selected";
        return s;
    }

private:
    bool valid(int row) const { return row >= 0 && row < count(); }
    const Item& item(int row) const { return m_items[static_cast<std::size_t>(m_rows[static_cast<std::size_t>(row)])]; }

    int rowOf(int id) const
    {
        for (int r{ 0 }; r < count(); ++r) if (idAt(r) == id) return r;
        return -1;
    }

    bool before(const Item& a, const Item& b) const
    {
        if (m_column == 1 && a.size != b.size) return a.size < b.size;
        if (m_column == 2 && a.modified != b.modified) return a.modified < b.modified;
        if (naturalLess(a.name, b.name)) return true;
        if (naturalLess(b.name, a.name)) return false;
        return a.id < b.id;
    }

    void rebuild()
    {
        m_rows.clear();
        for (std::size_t i{ 0 }; i < m_items.size(); ++i)
            if (m_filter.empty() || lower(m_items[i].name).find(m_filter) != std::string::npos) m_rows.push_back(static_cast<int>(i));
        std::sort(m_rows.begin(), m_rows.end(), [&](int x, int y) {
            const Item& a{ m_items[static_cast<std::size_t>(x)] };
            const Item& b{ m_items[static_cast<std::size_t>(y)] };
            return m_ascending ? before(a, b) : before(b, a);
        });
    }

    std::vector<Item> m_items;
    std::vector<int> m_rows;
    std::string m_filter;
    int m_column{ 0 };
    bool m_ascending{ true };
    std::set<int> m_selected;
    int m_anchor{ -1 };
};

unitTests:
using Ids = std::vector<int>;
std::vector<Item> files() {
    return { { 1, "report10.pdf", 2'500'000, "2026-03-01 09:00" }, { 2, "Report2.pdf", 1536, "2026-01-15 17:30" },
             { 3, "notes.txt", 800, "2026-03-01 09:00" }, { 4, "photo.jpg", 2'500'000, "2025-12-24 20:15" }, { 5, "report1.pdf", 12, "2026-02-02 08:00" } };
}
Ids order(const ResultList& l) { Ids v; for (int r = 0; r < l.count(); ++r) v.push_back(l.idAt(r)); return v; }
TEST("sorting") {
    ResultList l; l.setItems(files()); CHECK_EQ(order(l), (Ids{ 3, 4, 5, 2, 1 }));
    l.clickColumn(0); CHECK(!l.ascending()); CHECK_EQ(order(l), (Ids{ 1, 2, 5, 4, 3 }));
    l.clickColumn(1); CHECK(l.ascending()); CHECK_EQ(l.sortColumn(), 1); CHECK_EQ(order(l), (Ids{ 5, 3, 2, 4, 1 }));
    l.clickColumn(2); CHECK_EQ(order(l), (Ids{ 4, 2, 5, 3, 1 })); l.clickColumn(2); CHECK_EQ(order(l), (Ids{ 1, 3, 5, 2, 4 }));
}
TEST("cells") { ResultList l; l.setItems(files()); CHECK_EQ(l.cellText(0, 0), std::string("notes.txt")); CHECK_EQ(l.cellText(0, 1), std::string("800 bytes")); CHECK_EQ(l.cellText(1, 1), std::string("2.38 MB")); CHECK_EQ(l.cellText(3, 2), std::string("2026-01-15 17:30")); CHECK_EQ(l.cellText(9, 0), std::string("")); }
TEST("filtering") {
    ResultList l; l.setItems(files()); l.setFilter("REPORT"); CHECK_EQ(order(l), (Ids{ 5, 2, 1 })); CHECK_EQ(l.status(), std::string("3 of 5 items shown"));
    l.setFilter(""); CHECK_EQ(l.count(), 5); CHECK_EQ(l.status(), std::string("5 items"));
}
TEST("selection") {
    ResultList l; l.setItems(files());
    l.click(1); CHECK_EQ(l.selectedIds(), (Ids{ 4 })); l.shiftClick(3); CHECK_EQ(l.selectedIds(), (Ids{ 4, 5, 2 }));
    l.ctrlClick(0); CHECK_EQ(l.selectedIds(), (Ids{ 3, 4, 5, 2 })); l.ctrlClick(2); CHECK_EQ(l.selectedIds(), (Ids{ 3, 4, 2 }));
    l.shiftClick(4); CHECK_EQ(l.selectedIds(), (Ids{ 5, 2, 1 })); CHECK_EQ(l.status(), std::string("5 items, 3 selected"));
}
TEST("selection survives sorting and filtering") {
    ResultList l; l.setItems(files()); l.click(0); l.ctrlClick(4);
    l.clickColumn(1); CHECK_EQ(l.selectedIds(), (Ids{ 3, 1 }));
    l.setFilter("pdf"); CHECK_EQ(l.selectedIds(), (Ids{ 1 })); CHECK_EQ(l.status(), std::string("3 of 5 items shown, 1 selected"));
    l.setFilter(""); CHECK_EQ(l.selectedIds(), (Ids{ 1 }));
    l.shiftClick(0); CHECK_EQ(l.selectedIds(), (Ids{ 5, 3, 2, 4, 1 }));
}
TEST("new items") { ResultList l; l.setItems(files()); l.clickColumn(1); l.click(0); l.setFilter("x"); l.setItems({ { 9, "only.txt", 1, "2026-01-01 00:00" } }); CHECK_EQ(l.status(), std::string("1 item")); CHECK_EQ(l.sortColumn(), 1); CHECK(l.selectedIds().empty()); }

